import json,base64,html
r=Path(__file__).resolve().parents[1];c=json.loads((r/'candidates.json').read_text());rows=c['candidates'];pages=[]
def page(t,b):pages.append('<section><h1>'+t+'</h1>'+b+'</section>')
def link(u,t):return f'<a href="{html.escape(u)}">{html.escape(t)}</a>'
def uri(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
def image(p,label):return '<figure><img src="'+uri(p)+'"><figcaption>'+label+'</figcaption></figure>'
def table(head,body):return '<table><tr>'+''.join('<th>'+h+'</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in body)+'</table>'
